#!/bin/bash
echo '=== aremhub AWS Otomatik Kurulum Baþlýyor ==='
sudo apt update && sudo apt install -y nginx certbot python3-certbot-nginx

echo '' | base64 -d | gunzip | sudo tee /var/www/html/index.html > /dev/null

echo '=== Nginx Yeniden Baþlatýlýyor ==='
sudo systemctl restart nginx

echo '=== SSL Sertifikasý Alýnýyor ==='
sudo certbot --nginx -d aremhub.com -d www.aremhub.com --non-interactive --agree-tos --register-unsoundly-if-necessary -m bilgi@aremhub.com || true

echo '=== KURULUM TAMAMLANDI! ==='
